import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"六丑·正单衣试酒恨","description":"","frontmatter":{"title":"六丑·正单衣试酒恨","date":"2026-11-18T00:00:00.000Z","seq":237,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"poem_quote":false,"author":"周邦彦","source_book":"宋词三百首","prev":{"text":"花犯·粉墙低梅花照","link":"/blogs/宋词三百首/花犯·粉墙低梅花照.html"},"next":{"text":"兰陵王·柳阴直","link":"/blogs/宋词三百首/兰陵王·柳阴直.html"}},"headers":[],"relativePath":"blogs/宋词三百首/六丑·正单衣试酒恨.md","filePath":"blogs/宋词三百首/六丑·正单衣试酒恨.md"}'),o={name:"blogs/宋词三百首/六丑·正单衣试酒恨.md"};function l(n,a,c,m,_,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="六丑·正单衣试酒恨" tabindex="-1">六丑·正单衣试酒恨 <a class="header-anchor" href="#六丑·正单衣试酒恨" aria-label="Permalink to &quot;六丑·正单衣试酒恨&quot;">​</a></h1><p class="poem-meta">宋 · 周邦彦</p><div class="poem"><p class="poem-stanza">正单衣试酒，恨客里、光阴虚掷。</p><p class="poem-stanza">愿春暂留，春归如过翼。</p><p class="poem-stanza">一去无迹。</p><p class="poem-stanza">为问花何在，夜来风雨，葬楚宫倾国。</p><p class="poem-stanza">钗钿堕处遗香泽。</p><p class="poem-stanza">乱点桃蹊，轻翻柳陌。</p><p class="poem-stanza">多情为谁追惜。</p><p class="poem-stanza">但蜂媒蝶使，时叩窗隔。</p><p class="poem-stanza">东园岑寂。</p><p class="poem-stanza">渐蒙笼暗碧。</p><p class="poem-stanza">静绕珍丛底，成叹息。</p><p class="poem-stanza">长条故惹行客。</p><p class="poem-stanza">似牵衣待话，别情无极。</p><p class="poem-stanza">残英小、强簪巾帻。</p><p class="poem-stanza">终不似一朵，钗头颤袅，向人侧。</p><p class="poem-stanza">漂流处、莫趁潮汐。</p><p class="poem-stanza">恐断红、尚有相思字，何由见得。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
